<script setup lang="ts">
import {ref} from 'vue'
import {useAssistant} from '../../entities/assistant/model'
import type {Conversation} from '../../shared/interfaces/assistant'
import {datetime} from '../../shared/lib/format'
import {errorMessage} from '../../shared/api/client'
import Icon from '../../shared/ui/Icon.vue'
const store=useAssistant(),emit=defineEmits<{select:[]}>(),editing=ref<Conversation|null>(null),title=ref(''),deleting=ref<Conversation|null>(null),error=ref(''),busy=ref(false)
function edit(c:Conversation){editing.value={...c};title.value=c.title;error.value=''}
async function rename(){if(!editing.value||!title.value.trim())return;busy.value=true;try{await store.rename(editing.value.id,title.value.trim(),editing.value.version);editing.value=null}catch(e){error.value=errorMessage(e)}finally{busy.value=false}}
async function remove(){if(!deleting.value)return;busy.value=true;try{await store.remove(deleting.value.id);deleting.value=null}catch(e){error.value=errorMessage(e)}finally{busy.value=false}}
async function select(c:Conversation){emit('select');await store.selectConversation(c.id)}
</script>
<template><aside class="assistant-history" aria-label="История диалогов"><div class="assistant-history-heading"><h3>Мои диалоги</h3><button class="icon-button" aria-label="Новый диалог" :disabled="store.submitting" @click="store.newConversation();emit('select')"><Icon name="plus" :size="19"/></button></div><p class="assistant-history-hint">Только вы и эта компания</p><div class="assistant-history-scroll"><p v-if="store.listLoading&&!store.conversations.length" class="assistant-empty-small">Загружаем историю…</p><div v-if="store.listError" class="assistant-empty-small"><p class="assistant-error" role="alert">{{store.listError}}</p><button class="text-link" @click="store.loadList()">Повторить</button></div><p v-else-if="!store.listLoading&&!store.conversations.length" class="assistant-empty-small">Пока нет диалогов.<br>Начните с новой задачи.</p><div v-for="c in store.conversations" :key="c.id" class="assistant-history-item" :class="{active:store.conversation?.id===c.id}"><button class="assistant-conversation-button" :disabled="store.submitting" @click="select(c)"><b>{{c.title||'Новый диалог'}}</b><small>{{datetime(c.updated_at)}}<span v-if="c.active_run_id"> · выполняется</span></small></button><div class="assistant-history-actions"><button class="icon-button" aria-label="Переименовать диалог" :disabled="store.submitting" @click="edit(c)"><Icon name="settings" :size="13"/></button><button class="icon-button" aria-label="Удалить диалог" :disabled="store.submitting" @click="deleting=c;error='' "><Icon name="close" :size="13"/></button></div></div><button v-if="store.cursor" class="button small full" :disabled="store.listLoading" @click="store.loadList(true)">Ещё диалоги</button></div><form v-if="editing" class="assistant-history-edit" @submit.prevent="rename"><label>Название диалога<input v-model="title" maxlength="160" required/></label><div class="assistant-form-actions"><button type="button" class="text-link" @click="editing=null">Отмена</button><button class="button primary small" :disabled="busy">Сохранить</button></div><p v-if="error" class="assistant-error" role="alert">{{error}}</p></form><section v-if="deleting" class="assistant-history-edit" aria-label="Подтверждение удаления диалога"><b>Удалить этот диалог?</b><p>История и временные доступы будут удалены. Выполненные настройки компании сохранятся.</p><div class="assistant-form-actions"><button class="text-link" @click="deleting=null">Отмена</button><button class="button danger small" :disabled="busy" @click="remove">Удалить</button></div><p v-if="error" class="assistant-error" role="alert">{{error}}</p></section></aside></template>
